"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Portal } from "../lib/portal";
import { Slot } from "../lib/slot";
import { useControllableState, useEscapeKey, useFocusTrap, useLockScroll, usePresence } from "../lib/hooks";
import { Button } from "./button";
import { Icon } from "../icons/icon";

interface DialogContextValue {
  open: boolean;
  setOpen: (open: boolean) => void;
  titleId: string;
  descriptionId: string;
}

const DialogContext = React.createContext<DialogContextValue | null>(null);

function useDialog(component: string): DialogContextValue {
  const context = React.useContext(DialogContext);
  if (!context) throw new Error(`<${component}> moet binnen <Dialog> staan.`);
  return context;
}

export interface DialogProps {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  children?: React.ReactNode;
}

/** Dialog — modaal venster met overlay, focus-trap en Escape-afhandeling. */
export function Dialog({ open, defaultOpen = false, onOpenChange, children }: DialogProps) {
  const [isOpen, setIsOpen] = useControllableState<boolean>({
    value: open,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  });
  const id = React.useId();

  return (
    <DialogContext.Provider
      value={{
        open: isOpen,
        setOpen: setIsOpen,
        titleId: `lui-dialog-title-${id}`,
        descriptionId: `lui-dialog-desc-${id}`,
      }}
    >
      {children}
    </DialogContext.Provider>
  );
}

export interface DialogTriggerProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  asChild?: boolean;
}

export const DialogTrigger = React.forwardRef<HTMLButtonElement, DialogTriggerProps>(
  function DialogTrigger({ asChild, onClick, ...rest }, ref) {
    const { setOpen } = useDialog("DialogTrigger");
    const Comp = (asChild ? Slot : "button") as React.ElementType;
    return (
      <Comp
        ref={ref}
        type={asChild ? undefined : "button"}
        onClick={(event: React.MouseEvent<HTMLButtonElement>) => {
          onClick?.(event);
          setOpen(true);
        }}
        {...rest}
      />
    );
  }
);

/** Sluit de dialog; wikkel er een knop in met `asChild`. */
export const DialogClose = React.forwardRef<HTMLButtonElement, DialogTriggerProps>(function DialogClose(
  { asChild, onClick, ...rest },
  ref
) {
  const { setOpen } = useDialog("DialogClose");
  const Comp = (asChild ? Slot : "button") as React.ElementType;
  return (
    <Comp
      ref={ref}
      type={asChild ? undefined : "button"}
      onClick={(event: React.MouseEvent<HTMLButtonElement>) => {
        onClick?.(event);
        setOpen(false);
      }}
      {...rest}
    />
  );
});

export interface DialogContentProps extends React.HTMLAttributes<HTMLDivElement> {
  size?: "sm" | "md" | "lg" | "xl" | "full";
  /** Verbergt het kruisje rechtsboven. */
  hideClose?: boolean;
  /** Klik op de overlay sluit niet. */
  static?: boolean;
}

export const DialogContent = React.forwardRef<HTMLDivElement, DialogContentProps>(
  function DialogContent(
    { size = "md", hideClose, static: isStatic, className, children, ...rest },
    ref
  ) {
    const { open, setOpen, titleId, descriptionId } = useDialog("DialogContent");
    const panelRef = React.useRef<HTMLDivElement>(null);

    const { render, state } = usePresence(open, panelRef);

    useEscapeKey(() => setOpen(false), open);
    useLockScroll(open);
    useFocusTrap(panelRef, open);

    if (!render) return null;

    return (
      <Portal>
        <div
          className="lui-overlay"
          data-state={state}
          onMouseDown={(event) => {
            if (event.target !== event.currentTarget) return;
            if (!isStatic) {
              setOpen(false);
              return;
            }
            // Statisch: niet sluiten, maar kort "veren" zodat duidelijk is dat
            // je eerst een keuze moet maken.
            const panel = panelRef.current;
            if (!panel || typeof panel.animate !== "function") return;
            if (window.matchMedia?.("(prefers-reduced-motion: reduce)").matches) return;
            panel.animate(
              [{ transform: "scale(1)" }, { transform: "scale(1.025)" }, { transform: "scale(.995)" }, { transform: "scale(1)" }],
              { duration: 320, easing: "cubic-bezier(.3, 1.3, .5, 1)" }
            );
          }}
        >
          <div className="lui-overlay-blur" aria-hidden="true" />
          <div
            ref={(node) => {
              (panelRef as React.MutableRefObject<HTMLDivElement | null>).current = node;
              if (typeof ref === "function") ref(node as HTMLDivElement);
              else if (ref) (ref as React.MutableRefObject<HTMLDivElement | null>).current = node;
            }}
            role="dialog"
            aria-modal="true"
            aria-labelledby={titleId}
            aria-describedby={descriptionId}
            tabIndex={-1}
            data-state={state}
            className={cn("lui-dialog", `lui-dialog-${size}`, className)}
            {...rest}
          >
            {!hideClose && (
              <Button
                variant="ghost"
                size="sm"
                className="lui-dialog-close"
                aria-label="Sluiten"
                icon={<Icon name="x" size={16} />}
                onClick={() => setOpen(false)}
              />
            )}
            {children}
          </div>
        </div>
      </Portal>
    );
  }
);

export const DialogHeader = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  function DialogHeader({ className, ...rest }, ref) {
    return <div ref={ref} className={cn("lui-dialog-header", className)} {...rest} />;
  }
);

export const DialogTitle = React.forwardRef<HTMLHeadingElement, React.HTMLAttributes<HTMLHeadingElement>>(
  function DialogTitle({ className, ...rest }, ref) {
    const { titleId } = useDialog("DialogTitle");
    return <h2 ref={ref} id={titleId} className={cn("lui-dialog-title", className)} {...rest} />;
  }
);

export const DialogDescription = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(function DialogDescription({ className, ...rest }, ref) {
  const { descriptionId } = useDialog("DialogDescription");
  return <p ref={ref} id={descriptionId} className={cn("lui-dialog-description", className)} {...rest} />;
});

export const DialogBody = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  function DialogBody({ className, ...rest }, ref) {
    return <div ref={ref} className={cn("lui-dialog-body", className)} {...rest} />;
  }
);

export const DialogFooter = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  function DialogFooter({ className, ...rest }, ref) {
    return <div ref={ref} className={cn("lui-dialog-footer", className)} {...rest} />;
  }
);

/* ============================ Overlay (gedeeld) ============================ */
.lui-overlay {
  position: fixed; inset: 0; z-index: var(--z-overlay);
  display: grid; place-items: center; padding: 24px;
  background: var(--overlay);
  animation: lui-overlay-in .15s var(--ease) both;
}
.lui-overlay-blur {
  position: absolute; inset: 0; pointer-events: none;
  backdrop-filter: blur(3px); -webkit-backdrop-filter: blur(3px);
}

/* ============================ Dialog ============================ */
.lui-dialog {
  position: relative;
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--r-xl); box-shadow: var(--sh-xl);
  width: 100%; max-width: calc(100vw - 48px); max-height: calc(100vh - 48px);
  display: flex; flex-direction: column; overflow: hidden;
  animation: lui-dialog-in .22s var(--ease-out) both;
}
@keyframes lui-dialog-in {
  from { opacity: 0; transform: translateY(8px) scale(.96); }
  to { opacity: 1; transform: none; }
}

.lui-dialog-sm { max-width: min(380px, calc(100vw - 48px)); }
.lui-dialog-md { max-width: min(480px, calc(100vw - 48px)); }
.lui-dialog-lg { max-width: min(640px, calc(100vw - 48px)); }
.lui-dialog-xl { max-width: min(840px, calc(100vw - 48px)); }
.lui-dialog-full { max-width: calc(100vw - 48px); width: 100%; height: calc(100vh - 48px); }

.lui-dialog-close { position: absolute; top: 14px; right: 14px; z-index: 1; }

.lui-dialog-header { padding: 22px 22px 0; padding-right: 52px; display: flex; flex-direction: column; gap: 5px; }
.lui-dialog-title { font-size: var(--fs-xl); font-weight: 650; letter-spacing: -0.02em; color: var(--text); }
.lui-dialog-description { font-size: 13.5px; color: var(--text-3); line-height: 1.5; }
.lui-dialog-body { padding: 18px 22px; overflow-y: auto; flex: 1; min-height: 0; }
.lui-dialog-header + .lui-dialog-body { padding-top: 16px; }
.lui-dialog-footer {
  display: flex; gap: 10px; justify-content: flex-end;
  padding: 4px 22px 20px; flex: none;
}

@media (max-width: 560px) {
  .lui-overlay { padding: 14px; }
  .lui-dialog-footer { flex-direction: column-reverse; }
  .lui-dialog-footer > * { width: 100%; justify-content: center; }
}

/* ---------- Sluiten ---------- */
.lui-overlay[data-state="closed"] { animation: lui-overlay-out .16s var(--ease) both; }
.lui-dialog[data-state="closed"] { animation: lui-dialog-out .16s var(--ease) both; }

@keyframes lui-overlay-out { from { opacity: 1; } to { opacity: 0; } }
@keyframes lui-dialog-out {
  from { opacity: 1; transform: none; }
  to { opacity: 0; transform: translateY(6px) scale(.98); }
}

@media (prefers-reduced-motion: reduce) {
  .lui-dialog, .lui-dialog[data-state="closed"],
  .lui-overlay, .lui-overlay[data-state="closed"] { animation-duration: .01ms; }
}
